import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"Players & the registry","description":"","frontmatter":{},"headers":[],"relativePath":"gamekit/reference/players.md","filePath":"vendored/gamekit/reference/players.md"}`),a={name:`gamekit/reference/players.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="players-the-registry" tabindex="-1">Players &amp; the registry <a class="header-anchor" href="#players-the-registry" aria-label="Permalink to “Players &amp; the registry”">​</a></h1><p>A player is a folder in <code>gamekit/players/</code> — a docstring carrying the measured record, a <code>SPECS</code> tuple of <code>PlayerSpec</code> rows, and a <code>make</code> arm factory. The registry (<code>gamekit.players.registry</code>) maps name → spec so drivers and CLIs enumerate arms from one table.</p><h2 id="the-roster" tabindex="-1">The roster <a class="header-anchor" href="#the-roster" aria-label="Permalink to “The roster”">​</a></h2><table tabindex="0"><thead><tr><th>player</th><th>kind</th></tr></thead><tbody><tr><td><code>random</code></td><td>chance — the paired baseline every eval runs against</td></tr><tr><td><code>playbook</code></td><td>scripted — the hand-written moves</td></tr><tr><td><code>linear</code> (<code>linear-greedy</code>, <code>linear-cold</code>)</td><td>the trained linear prior — a featurizer-injected <code>LinearPolicy</code></td></tr><tr><td><code>neural</code></td><td>the neural arm</td></tr><tr><td><code>distilled</code></td><td>the distilled contraction-ordering player</td></tr><tr><td><code>gated</code></td><td>the <code>GatedPlayer</code> — an isolated stop channel with a <code>forced_action</code> hook</td></tr></tbody></table><h2 id="playerspec-—-the-registration-contract" tabindex="-1"><code>PlayerSpec</code> — the registration contract <a class="header-anchor" href="#playerspec-—-the-registration-contract" aria-label="Permalink to “PlayerSpec — the registration contract”">​</a></h2><p><code>name</code> / <code>kind</code> (<code>chance</code> | <code>scripted</code> | <code>linear</code> | <code>neural</code> | <code>distilled</code>) / <code>boards</code> / <code>schema</code> / <code>train</code> / <code>artifact</code> / <code>record</code> / <code>variant</code>. <code>boards</code> is the honest capability statement — list only what <code>make</code> accepts; <code>record</code> is the one-line measured claim that earns the seat; <code>variant</code> carries decode/weights flags the factory reads.</p><h2 id="the-registry-surface" tabindex="-1">The registry surface <a class="header-anchor" href="#the-registry-surface" aria-label="Permalink to “The registry surface”">​</a></h2><p><code>names()</code>, <code>spec(name)</code>, <code>specs()</code>, <code>for_board(board)</code>, <code>module(name)</code>, <code>BOARDS</code>/<code>EPISODE_BOARDS</code>, and <strong><code>make(name, domain, *, seed=0, ctx=None) -&gt; (i -&gt; player)</code></strong> — raises <code>ValueError</code> on an unplayed board, never a silent run. <code>register_player</code> is the plugin seam downstream domains use to seat new arms. Loading is lazy: folders import on first <code>spec()</code>/<code>make()</code>.</p><h2 id="the-machinery" tabindex="-1">The machinery <a class="header-anchor" href="#the-machinery" aria-label="Permalink to “The machinery”">​</a></h2><p><code>gamekit.players._base</code> — <code>LinearPolicy</code>, <code>DomainSpec</code> (incl. <code>to_record</code>/<code>build_from_record</code>), <code>LearnedPlayer</code>, <code>GatedPlayer</code>, <code>PlayHist</code>, the composable feature parts (<code>Bias</code>, <code>StateBroadcast</code>, <code>PlayRates</code>, <code>OpOneHot</code>, <code>ActionFeats</code>, <code>RelFeats</code>, <code>compose_featurizer</code>), and the <code>register_part</code>/<code>register_legal</code>/ <code>register_rank</code> + <code>PARTS</code>/<code>LEGALS</code>/<code>RANKS</code> registries.</p><h2 id="recipes-records" tabindex="-1">Recipes &amp; records <a class="header-anchor" href="#recipes-records" aria-label="Permalink to “Recipes &amp; records”">​</a></h2><ul><li><a href="/docs/graphopt/how-to/register-a-player.html">Register a player</a> — the full recipe (the <code>make</code> contract, the <code>_MODULES</code> table, the measured record).</li><li><a href="/docs/graphopt/reference/leaderboard.html">The player leaderboard</a> — the published measured records.</li></ul><p>Source: <a href="https://github.com/handl-lang/gamekit/tree/main/packages/gamekit/src/gamekit/players" target="_blank" rel="noreferrer"><code>gamekit/players/</code></a>.</p>`,13)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};